<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {api,post} from '../api'
import {usePolling} from '../usePolling'
import {useMarketStore} from '../store'
import {number,price,time} from '../format'
import {rankSpec,specKey} from '../speculative'
import type {SpecSnapshot,SpecRow,SpecAudit,Binding} from '../speculative'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import FeatureValue from '../components/FeatureValue.vue'
import Pager from '../components/Pager.vue'
const snapshot=ref<SpecSnapshot|null>(null);const bindings=ref<Binding[]>([]);const audit=ref<SpecAudit[]>([]);const store=useMarketStore()
const search=ref('');const source=ref('selected');const onlyCandidates=ref(false);const page=ref(0);const selected=ref<SpecRow|null>(null)
const busy=ref(false);const confirmed=ref(false);const actionError=ref('');const message=ref('');const editRevision=ref(0)
async function load(signal?:AbortSignal){const [s,b]=await Promise.all([api<SpecSnapshot>('/api/speculative',{signal}),api<Binding[]>('/api/venues/bindings',{signal})]);snapshot.value=s;bindings.value=b;await store.refresh(signal)}
const {error,refresh}=usePolling(signal=>load(signal),10000)
const rows=computed(()=>(snapshot.value?.rows??[]).filter(r=>r.input.market.instrument.symbol.toLowerCase().includes(search.value.trim().toLowerCase())&&(source.value==='all'||source.value==='selected'&&r.isSelectedSource||r.input.exchange===source.value)&&(!onlyCandidates.value||r.assessment.isCandidate)).sort(rankSpec))
const paged=computed(()=>rows.value.slice(page.value*30,(page.value+1)*30));watch([search,source,onlyCandidates],()=>page.value=0)
const chosen=computed(()=>(snapshot.value?.rows??[]).filter(r=>r.isSelectedSource))
const health=computed(()=>store.health.filter(h=>/Gate|Coinbase|Cooldown|Speculative/.test(h.health.name)))
function select(r:SpecRow){if(busy.value)return;selected.value=r;confirmed.value=false;actionError.value='';message.value='';editRevision.value=bindings.value.find(b=>b.assetId===r.input.market.instrument.assetId&&b.exchange===r.input.exchange)?.revision??0}
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;actionError.value='';try{await work()}catch(e){actionError.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
const scan=()=>run(async()=>{snapshot.value=await post<SpecSnapshot>('/api/speculative/refresh')})
const check=()=>run(async()=>{audit.value=await api('/api/speculative/audit?limit=3')})
const bind=(revoke=false)=>run(async()=>{const r=selected.value;if(!r||r.input.exchange!=='Gate'||!revoke&&!confirmed.value)return;await api(`/api/venues/bindings/${r.input.market.instrument.assetId}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({exchange:r.input.exchange,symbol:r.input.nativeSymbol,expectedRevision:editRevision.value,confirmIdentity:confirmed.value,revoke})});confirmed.value=false;await load();snapshot.value=await post('/api/speculative/refresh');selected.value=snapshot.value!.rows.find(x=>specKey(x)===specKey(r))??null;editRevision.value=bindings.value.find(b=>b.assetId===r.input.market.instrument.assetId&&b.exchange===r.input.exchange)?.revision??0;message.value=revoke?'Gate 身份确认已撤销，修改记录保留。':'跨交易所身份已保存；还需在资产映射页确认 CoinGecko ID，且输入必须新鲜。'})
</script>
<template><PageIntro eyebrow="SPECULATIVE RADAR · V1" title="异常值得看，风险另行判断。" description="低市值、高 OI 与成交异常分开核对，按交易所保留原始证据。"><button class="replay-action" :disabled="busy" @click="scan">{{busy?'处理中…':'重新计算缓存'}}</button></PageIntro>
<p v-if="error||actionError" class="radar-notice" role="alert">{{actionError||error}}</p><p class="radar-notice">固定 100 权重，仅计算已观测贡献，不放大缺失项。链上筹码与 Holder 变化需通过身份、分类覆盖与基线门槛；钱包行为仍未知，风险分低不等于安全。此页与 V2 并行，不触发实际通知。</p>
<div class="stats"><StatCard label="永续观察标的" :value="chosen.length" foot="Binance 优先，输入不足时展示 Gate 参考"/><StatCard label="必要输入与身份可用" :value="chosen.filter(r=>r.assessment.anomalyScore!==null).length" foot="需核对 CoinGecko 与跨交易所身份"/><StatCard label="观察候选" :value="chosen.filter(r=>r.assessment.isCandidate).length" foot="异常阈值 + 两类确认 + 非过热"/><StatCard label="过热标的" :value="chosen.filter(r=>r.assessment.stage==='Overheated').length" foot="异常程度与风险程度独立"/></div>
<div class="provider-grid"><div v-for="h in health" :key="h.health.name" class="provider"><div><b>{{h.health.name}}</b><span class="health" :class="h.status.toLowerCase()">{{h.status}}</span></div><span>{{time(h.health.lastSuccess)}}</span><p v-if="h.health.error" class="provider-error">{{h.health.error}}</p></div></div>
<div class="section-heading"><h2>妖币雷达 · 独立交易所观察</h2><span class="refresh-text">{{snapshot?.strategyVersion}} · {{time(snapshot?.asOf)}} · 默认 5 分钟计算</span></div><div class="market-panel"><div class="toolbar"><label class="search"><input v-model="search" aria-label="搜索投机雷达合约" placeholder="搜索合约，例如 ARIA"></label><select v-model="source" aria-label="投机数据来源"><option value="selected">主来源 · Binance</option><option value="all">全部来源对照</option><option value="Binance">Binance 永续</option><option value="Gate">Gate 永续</option><option value="Coinbase">Coinbase 现货参考</option></select><label class="checkbox"><input v-model="onlyCandidates" type="checkbox">仅观察候选</label><span class="results">{{rows.length}} 个结果</span></div><div class="table-scroll"><table><thead><tr><th>本地合约 / 来源</th><th>价格</th><th>市值 USD</th><th>OI USD</th><th>异常分 ↓ / 覆盖</th><th>风险分 / 覆盖</th><th>阶段 / 身份</th><th>核对</th></tr></thead><tbody><tr v-for="r in paged" :key="specKey(r)"><td>{{r.input.market.instrument.symbol}}<small>{{r.input.exchange}} · {{r.input.nativeSymbol}}{{r.isSelectedSource?' · 主来源':' · 备用参考'}}</small></td><td>{{price(r.input.price.value)}}<small>{{time(r.input.price.sourceTime)}}</small></td><td><FeatureValue :feature="r.input.market.features.capital?.marketCapUsd"/></td><td><FeatureValue :feature="r.input.openInterestUsd"/></td><td>{{number(r.assessment.anomalyScore,1)}}<small>{{r.assessment.anomalyCoverage}} / 100 权重可用</small></td><td>{{number(r.assessment.riskScore,1)}}<small>{{r.assessment.riskCoverage}} / 100 权重可用</small></td><td>{{r.assessment.stage}}<small>{{r.input.market.features.capital?.trustedIdentity&&r.input.venueIdentityVerified?'身份已核对':'身份待核对'}}</small></td><td><button class="text-button" @click="select(r)">依据 →</button></td></tr><tr v-if="!rows.length"><td colspan="8" class="empty">暂无符合条件的结果。可以关闭候选筛选，查看输入与身份缺口。</td></tr></tbody></table></div><Pager v-model="page" :total="rows.length">不同交易所独立计算，不相加 OI；USDT 金额作为 USD 代理口径。</Pager></div>
<section v-if="selected" class="detail"><div class="section-heading"><h2>{{selected.input.market.instrument.symbol}} · {{selected.input.exchange}} · 评分依据</h2><button class="text-button" @click="selected=null">收起 ×</button></div><p>{{selected.assessment.reason}}</p><p>{{selected.input.sourceNote}}</p><p>{{message}}</p><RouterLink :to="{path:'/mappings',query:{symbol:selected.input.market.instrument.symbol}}">核对该资产的 CoinGecko 身份 →</RouterLink><div v-if="selected.input.exchange==='Gate'&&!selected.input.venueIdentityVerified" class="detail"><p>确认 {{selected.input.nativeSymbol}} 与本地 {{selected.input.market.instrument.symbol}} 是同一资产。符号相同仅为候选依据，合约倍数与资产迁移应另外核查。</p><label class="checkbox"><input v-model="confirmed" type="checkbox" aria-label="确认 Gate 合约身份">我已核对两个交易所的原生合约身份。</label><button class="replay-action" :disabled="busy||!confirmed" @click="bind(false)">保存 Gate 身份核对</button></div>
<button v-if="selected.input.exchange==='Gate'&&selected.input.venueIdentityVerified" class="text-button" :disabled="busy" @click="bind(true)">撤销 Gate 身份确认</button><div class="detail-grid"><div><span>24h 永续成交额</span><strong><FeatureValue :feature="selected.input.volume24hUsd"/></strong></div><div><span>OI 数量变化 · 15m</span><strong><FeatureValue :feature="selected.input.oiChange15m" suffix="%"/></strong></div><div><span>OI RZ</span><strong><FeatureValue :feature="selected.input.oiRobustZ"/></strong></div><div><span>8h 标准化 Funding</span><strong><FeatureValue :feature="selected.input.fundingRate8h" :multiplier="100" suffix="%"/></strong></div></div>
<template v-for="group in [{title:'异常程度',items:selected.assessment.anomalyComponents},{title:'风险程度',items:selected.assessment.riskComponents}]" :key="group.title"><h3>{{group.title}} · 固定权重与贡献</h3><div class="table-scroll"><table><thead><tr><th>指标</th><th>权重</th><th>强度 / 贡献</th><th>证据</th><th>源时间</th></tr></thead><tbody><tr v-for="c in group.items" :key="c.family"><td>{{c.family}}</td><td>{{c.weight}}</td><td>{{number(c.strength)}} / {{number(c.strength===null?null:c.strength*c.weight)}}</td><td class="decision-reason">{{c.description}}</td><td>{{time(c.sourceTime)}}</td></tr></tbody></table></div></template><p>缺失证据：{{selected.assessment.missingFamilies.join(' · ')}}</p>
<p v-if="selected.binanceUp">同期 Binance V2：上涨 {{number(selected.binanceUp.score,1)}} / {{selected.binanceUp.strategyVersion}}；下跌 {{number(selected.binanceDown?.score,1)}} / {{selected.binanceDown?.strategyVersion}}。模型目标和权重不同，不能直接比较分数大小。</p></section>
<div class="section-heading radar-heading"><h2>历史输入复算</h2><button class="replay-action" :disabled="busy" @click="check">复核最近三次扫描</button></div><p class="radar-notice">保存本轮输入、身份状态和参数，保留 7 天。此处检验可复现性，命中率仍需成熟行情和后续统计，不能用复算一致替代策略有效性。</p><div v-if="audit.length" class="market-panel table-scroll"><table><thead><tr><th>历史扫描</th><th>结果</th><th>记录 / 差异</th><th>依据</th></tr></thead><tbody><tr v-for="a in audit" :key="a.id"><td>{{time(a.asOf)}}</td><td>{{a.status}}</td><td>{{a.rows}} / {{a.mismatches}}</td><td>{{a.reason}}</td></tr></tbody></table></div>
</template>
